// Compare compiled controllers in dist-server with the compiled baseline (po-s08-baseline).
// Usage: node cmp-compiled.js <repoRoot> <baselineRoot> Name1 Name2 ...   (names without "Controller")
// Lines that are only comments, blank, "use strict" or require lines are set aside and listed separately;
// every other difference is printed as CODE DIFF and has to be explained.
const fs = require('fs')
const path = require('path')

const [repoRoot, baselineRoot, ...names] = process.argv.slice(2)

const isComment = (l) => /^\s*(\/\/|\/\*|\*)/.test(l)
const isRequire = (l) => /^\s*(const|let|var)\s+[^=]+=\s*require\([^)]*\)(\.\w+)?;?\s*$/.test(l)
// `const { a, b } = x;` right after `const x = require(...)` (the CommonJS shape from CLAUDE.md)
const isDestructureOfIdent = (l) => /^\s*const\s+\{[^}]*\}\s*=\s*[A-Za-z_$][\w$]*;?\s*$/.test(l)
const isNoise = (l) => l.trim() === '' || l.trim() === '"use strict";' || isComment(l)
// strip a trailing line comment (not inside a string: good enough for a review aid)
const stripTrailing = (l) => l.replace(/\s+\/\/ .*$/, '')

function split(file) {
  const lines = fs.readFileSync(file, 'utf8').split(/\r?\n/)
  const code = []
  const imports = []
  for (const raw of lines) {
    if (isNoise(raw)) continue
    if (isRequire(raw) || isDestructureOfIdent(raw)) {
      imports.push(raw.trim())
      continue
    }
    code.push(stripTrailing(raw))
  }
  return { code, imports }
}

// simple LCS diff, files are small
function diff(a, b) {
  const n = a.length
  const m = b.length
  const dp = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
  const out = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) out.push('- ' + a[i++])
    else out.push('+ ' + b[j++])
  }
  while (i < n) out.push('- ' + a[i++])
  while (j < m) out.push('+ ' + b[j++])
  return out
}

let bad = 0
for (const name of names) {
  const rel = path.join('server', 'controllers', name + 'Controller.js')
  const basePath = path.join(baselineRoot, rel)
  const newPath = path.join(repoRoot, 'dist-server', rel)
  if (!fs.existsSync(newPath)) {
    console.log(`## ${name}: MISSING ${newPath}`)
    bad++
    continue
  }
  const base = split(basePath)
  const cur = split(newPath)
  const codeDiff = diff(base.code, cur.code)
  const importDiff = diff(base.imports, cur.imports)
  console.log(`## ${name}: code lines ${base.code.length} -> ${cur.code.length}, CODE DIFF lines: ${codeDiff.length}, import diff lines: ${importDiff.length}`)
  if (codeDiff.length) {
    bad++
    console.log(codeDiff.map((l) => '   CODE ' + l).join('\n'))
  }
  if (importDiff.length && process.env.SHOW_IMPORTS) console.log(importDiff.map((l) => '   imp  ' + l).join('\n'))
}
console.log(bad ? `\n${bad} file(s) with code differences` : '\nno code differences')

