    if (thisApi) c.thisApi += thisApi.length
    const casts = code.match(/\bas\s+(?!const\b)[A-Za-z_{(\[][^,;)]*/g)
    if (casts) {
      for (const cast of casts) {
        if (/^as\s+unknown\b/.test(cast)) {
          c.a1++
          notes.push(`cast-1 ${n}: ${t.trim()}`)
        } else if (/^as\s+Error\b/.test(cast)) {
          c.a2++
          if (detail) notes.push(`cast-2 ${n}: ${t.trim()}`)
        } else if (/^as\s+Parameters</.test(cast)) {
          c.a3++
          notes.push(`cast-3 ${n}: ${t.trim()}`)
        } else {
          c.other++
          notes.push(`cast-o ${n}: ${t.trim()}`)
        }
      }
    }
    if (/\bas const\b/.test(code)) notes.push(`const  ${n}: ${t.trim()}`)
  }
  rows.push(c)
  for (const k of ['bang', 'index', 'a1', 'a2', 'a3', 'other', 'thisApi', 'banned']) add(k, c[k])
  console.log(`${short.padEnd(24)} +${String(c.added).padEnd(4)} -${String(c.removed).padEnd(4)} !:${c.bang} idx:${c.index} cast[A1:${c.a1} A2:${c.a2} A3:${c.a3} other:${c.other}] this:${c.thisApi} banned:${c.banned}`)
  for (const note of notes) console.log('     ' + note)
}
console.log('TOTAL', JSON.stringify(totals))

